<script setup lang="ts">
import {ref,computed,onMounted} from 'vue';import {companyOptions,api,date,errorText} from '../api';import PageHeading from '../components/PageHeading.vue';import StatusBadge from '../components/StatusBadge.vue';import Modal from '../components/Modal.vue';import {Plus,Check} from 'lucide-vue-next';
const tasks=ref<any[]>([]),companies=ref<any[]>([]),team=ref<any[]>([]),error=ref(''),busy=ref(false),show=ref(false),view=ref('list');const form=ref({company_id:'',title:'',due_on:'',responsible_id:null as number|null,priority:'normal'});const groups=computed(()=>{const m=new Map<string,any[]>();for(const t of tasks.value){const day=t.due_on?.slice(0,10)||'Sin fecha';m.set(day,[...(m.get(day)||[]),t]);}return [...m.entries()];});async function load(){try{tasks.value=(await api.get('/tasks')).data;}catch(e){error.value=errorText(e);}}async function create(){busy.value=true;try{await api.post('/tasks',{...form.value,due_on:form.value.due_on||null});show.value=false;await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}async function complete(t:any){busy.value=true;try{await api.patch(`/tasks/${t.id}`,{status:t.status==='completed'?'pending':'completed'});await load();}catch(e){error.value=errorText(e);}finally{busy.value=false;}}onMounted(async()=>{await load();try{companies.value=await companyOptions();team.value=(await api.get('/team')).data;}catch(e){error.value=errorText(e);}});
</script>
<template><PageHeading title="Agenda y tareas" subtitle="Responsables y fechas de trabajo, sin perder el hilo."><button class="button primary" @click="show=true"><Plus :size="16"/>Nueva tarea</button></PageHeading><div class="filter-tabs tabs-large"><button @click="view='list'" :aria-pressed="view==='list'">Lista</button><button @click="view='agenda'" :aria-pressed="view==='agenda'">Agenda por fecha</button></div><p v-if="error" class="error" role="alert">{{error}}</p><section class="panel" v-if="view==='list'"><div v-for="t in tasks" :key="t.id" class="list-row"><button class="task-toggle" :class="{checked:t.status==='completed'}" :disabled="busy" @click="complete(t)" :aria-label="t.status==='completed'?'Reabrir tarea':'Completar tarea'"><Check v-if="t.status==='completed'" :size="15"/></button><div class="grow"><strong>{{t.title}}</strong><small>{{t.company.name}} · {{date(t.due_on)}} · {{team.find(u=>u.id===t.responsible_id)?.name||'Sin asignar'}}</small></div><span v-if="t.priority==='high'" class="badge correction">Prioridad alta</span><StatusBadge :status="t.status"/></div><p v-if="!tasks.length" class="empty">Crea una tarea para organizar el trabajo.</p></section><div v-else class="agenda-grid"><section class="panel" v-for="[day,items] in groups" :key="day"><div class="panel-heading"><h2>{{day==='Sin fecha'?day:date(day)}}</h2></div><div class="list-row" v-for="t in items" :key="t.id"><div><strong>{{t.title}}</strong><small>{{t.company.name}}</small></div><StatusBadge :status="t.status"/></div></section></div><p class="footnote">Las fechas corresponden a la agenda interna del estudio.</p><Modal v-if="show" title="Nueva tarea" @close="show=false"><form @submit.prevent="create" class="stack-form"><label>Empresa<select v-model="form.company_id" required><option value="" disabled>Selecciona empresa</option><option v-for="c in companies" :key="c.id" :value="c.id">{{c.name}}</option></select></label><label>Tarea<input v-model="form.title" required maxlength="180"></label><label>Fecha interna<input type="date" v-model="form.due_on"></label><label>Responsable<select v-model="form.responsible_id"><option :value="null">Sin asignar</option><option v-for="u in team" :value="u.id" :key="u.id">{{u.name}}</option></select></label><label>Prioridad<select v-model="form.priority"><option value="normal">Normal</option><option value="high">Alta</option></select></label><p v-if="error" class="error">{{error}}</p><button class="button primary" :disabled="busy">Crear tarea</button></form></Modal></template>
